) AS (
  VALUES 
    (212::BIGINT, 'Me esperaba mucho más de un profe doctor en física, la verdad. No es mala persona, pero su forma de enseñar es un desastre. La didáctica es terrible y a veces su explicación deja mucho que desear. Si puefe matricule con otro.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, '8332b2133d9c8debe291bc25e0587657636e342720cf5edd19ecd106074d3a5b'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Es muy cómico, se nota que le gusta lo que hace y es bastante estudiado (es ing civil y físico). Califica justo y siempre es muy pero MUY abierto a dar consulta. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd563cd86022acfaa64b10dcd8d009c20c79671bb6b4df8f0e70535ef176b076d'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Es un locazo, cae bien pero hay que tenerle cuidado, es sí es un curso sencillo que con su respectivo esfuerzo se pasa pero definitivamente hay mejores profes.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'b83829c4deb63dce6f3a96a24fca111a4a8b2a87080b1b00ea76d53b9a388a1a'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'No es mal profe y no califica duro pero si intente prestar atención porque si es algo estricto con ciertas cosas. Es muy correcto con la materia y a veces puede ser un toque casi sarcástico, es buena gente y da consejos para la vida.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, '9b57bb3e99f8a180120387d57dc02f8eb8cdcf162c745c70f8dbddb1b0241e13'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (212::BIGINT, 'No me creo que de verdad sea profesor. No sabe de la materia. Califica como si fuera el mismísimo Walpole. Las clases son shitposting. Estudie por su cuenta.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2025-12-05T00:00:00+00:00'::TIMESTAMPTZ, '1d9b07f2f858bc44989fea30a7478b3a7bf96fb459ee29e55dcbfef970d3db6b'::TEXT, ARRAY[3061]::BIGINT[]),
    (212::BIGINT, 'Es un profe estricto, pero da buena retroalimentación. Porfavor, comprométanse con el estudio y ser atentos a lo que el profe rubra. Es una buena opción, pero vayan estudiados desde el principio. Es un profe bastante considerado y atento. Además sus clases son muy buenas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'a64afae9b3c7a0a730fa8a70567fd208c3f26a8854bebf14f49780bdb6d49597'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Es un profesor normal, ayuda si uno le explica bien, pero a veces se confunde y hay que preguntarle mucho para estar claros. En los trabajos revisa bien.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'c72770a46bba6c6b4919e29005237103f8af17c9a029a31297d9632a4ed36bf8'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'El profesor siempre explica el laboratorio antes de iniciar, está siempre muy anuente a ayudar, incluso da horas de consulta extra. Califica de forma justa, da indicaciones muy claras y hace el curso sencillo y muy disfrutable.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-07T00:00:00+00:00'::TIMESTAMPTZ, '49d376ca2ac0dedf0182e075ef0e6eb33cd0ad9812e89eb1cedc2d24429a2659'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Explica muy bien lo que hay que hacer en la práctica. Si uno tiene dudas y le pregunta, él se va a asegurar de que usted entienda bien. Los informes los califica un poco rudo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'bc4c017092507b84991ff1636495ba85092e182e0c9d9ca394a14e36441bf889'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Buen profe, muy observativo a la hora de calificar tanto informes como practicas, si no lo hace bien pierde puntos, en lo personal a veces se enreda en hora de consulta, pero nada fuera de lo normal. Si usted no discute con él se lleva muy bien, explica lo que se debe hacer antes de lección.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2025-06-15T00:00:00+00:00'::TIMESTAMPTZ, '4ee106dd38a630faa691110cc64a1f5d723cff0aa3e0d61eb419cf60f7faa93e'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Buen profe, se confunde aveces con los excel de los infromes y se contradice pero si ayuda, buena nota cuando uno tiene dudas pero eso si, el explica lo que hay que hacer al inicio de la clase y si no se presta atención cuesta que repita lo explicado'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, '565fde8a4329b6686d6b80dca1760e637adda1a7e357bc7656fea6d459412c92'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'El profe dicen que antes era un poco complicado, ahorita la verdad es muy x, pregunte sin miedo, cosas que aja, siempre explica las cosas antes de hacerlas. Las evaluaciones son normales y la asistente también es un 10.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria']::TEXT[], '2025-05-21T00:00:00+00:00'::TIMESTAMPTZ, '85464ff352c388f9fa1623278eb0da06c44cdd8694e550cae550449b9f8c1630'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Hay muchas malas referencias a este profe, todas ellas son correctas. El profe es ignorante a la materia que imparte. Él piensa que es muy superior a todos los demás profes. Se desvía mucho de los temas, la materia no es difícil, pero dado su poco dominio asusta al estudiante. No lo matricule.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-19T00:00:00+00:00'::TIMESTAMPTZ, '1d00aac263aa27405dcf8fcf3a6a7f25675b69a37d3ef4a101ae73891005e052'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'Para lab de física 1 es bueno, tengo entendido que en teoría es malísimo, pero en lab es super chill, él revisa justo, explica al inicio y después se hace la práctica y él es muy pura vida como persona y pasar no es díficil con él, pero todo esto en LAB!'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'c76102af8b8a4b0190248c19bab1854404a1935d96619ad67036f4af7cdb0b11'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Es un profe un tanto duro, cree que uno no estudia si uno no entendió algo. Como persona no es mala pero como profesor no rinde. Es ingeniero pero de profesor no tiene mucho. Además, califica bastante fuerte y no suele perdonar puntos. Insiste en asistir a horas de consultas y suele dar tips.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2024-12-05T00:00:00+00:00'::TIMESTAMPTZ, '35a8134c0c26b8fc492dbb2cdb5d174c646553e3af696d8823eabc535cbeb09c'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'Los primeros 30 minutos de la clase no dice nada. No sabe explicar, calificar super duro. Se queja de que tiene mala nota en esta página pero no es buen profesor. No hace más que hacer la clase más peor y difícil de lo que verdaderamente es.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-10-22T00:00:00+00:00'::TIMESTAMPTZ, 'cb3d34e5ecb624b9864fccf1b28a9827fe4cdd716e27c082a50d6793c029af3a'::TEXT, ARRAY[631]::BIGINT[]),
    (212::BIGINT, 'Las clases no son del todo claras pero haciendo los ejemplos de las guías y repasando las presentaciones, uno se la juega. Lo importante de las presentaciones y de las clases son los ejercicios y las formuals que se usan para resolverlos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, '2338ee4a56792a4c929e69857307089da978e6d19d9a1c41da4bfbbf63e9771a'::TEXT, ARRAY[3061]::BIGINT[]),
    (212::BIGINT, 'El mae como persona no es malo, dicho esto pésimo profesor, no sabe dar clases. 30 min hablando de cosas sin importancia, además los primeros 30 min de la clases se la pasa recordando las tutorías, o cosas no importantes. Si pregunta algo prepárese para la explicación más larga y confusa posible.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Clases largas']::TEXT[], '2024-01-28T00:00:00+00:00'::TIMESTAMPTZ, '0b75b14c709541fd5fb4c9eeb4416c04ca0b6cf2ba67cca4d5550620db6e19fd'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'Pierde mucho tiempo hablando de cosas que no van al tema, por lo que lo más probable es que se atrase con la materia para el examen. Entonces si le toca llevarlo con él tiene que hacer un esfuerzo y buscar entender a materia por cuenta propia'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-08T00:00:00+00:00'::TIMESTAMPTZ, '5871e93b5c3da056bef8180567882b262f544ea1dc00917d5618de5fe1a63794'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'Tengo entendido que en otros cursos se para, pero si necesita llevar Lab de Fisica 1, y es su ultima opción matricule con él. Los primeros 30 minutos de la clase es él hablando de cualquier tontera para luego explicar lo que hay que hacer. Califica más o menos, siempre revise lo que pide la rubrica.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, '8f660625ab894560fca5ec79b1d538ac70122e80c5f4ad20728720f784929f5f'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Él es tuanis pero en cada clase se ponía a hablar de algún aspecto x de un estudiante que no le gustaba y eran 15 minutos de darle al tema hasta que se enojaba solo sin que nadie dijera nada. Si no tiene opción lleve con él pero hay que tener mucha paciencia'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-08T00:00:00+00:00'::TIMESTAMPTZ, '422933d3df26ec5de8ab6cdc50c2780756d413605d1e63f243fa8b7b3831d91b'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Como es común en el TEC, el mae es ingeniero, no profesor. Hace comentarios un tanto chocantes en clase. Desmerita el trabajo que hace uno, haciendo entender como que a uno le va mal simplemente porque es vago. El mae sí es justo en los exámenes. Vaya a clase, participe bastante y estudie con tiempo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '9dffe3983c29b1692e3e1e653048f618e85a53f21877a9a18d892d9e7ede9688'::TEXT, ARRAY[3049]::BIGINT[]),
    (212::BIGINT, 'Si es la primera ves que lleva el curso mejor busque otro...'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2023-11-21T00:00:00+00:00'::TIMESTAMPTZ, '3ce364961751bed99c7a33aa9dee8c63331d4e0d6914bdb217792b3d79e27af5'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'Hasta el momento es el peor profe que he tenido en el tec, se enreda mucho, aunque se nota que, si sabe, tiene una personalidad un poco grosera.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2023-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'ab4ca4b3a4ce1c0f4174014c3a1dc9332c3cae833acf3b06f85811da324cd8aa'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'El profe sabe mucho, pero se enreda hablando y explicando lo que hace que se lleven una clase en un tema muy facil. Hace pocos ejercicios en clase que no se parecen en nada al examen con la premisa de que le gusta que uno "piense", no da recomendados ni nada, solo lo manda a uno al libro y ya.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c00191ef48a15a6f5c7dadc331fc57eb04f5113a7b22dc540871c13e516a8345'::TEXT, ARRAY[3049]::BIGINT[]),
    (212::BIGINT, 'Como personalidad es pura vida, pero se enreda demasiado al dar las clases. En mi opinión hace muy pocos ejercicios y fáciles, para el nivel de dificultad de los exámenes . Además de que deja todo para lo último y olvídate de que te de puntos o que te deje un trabajo extra.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '349588163b55b2b13e57c710278b1b33da33c6fc8abda6ec84e460ac1120e824'::TEXT, ARRAY[3049]::BIGINT[]),
    (212::BIGINT, 'Nunca más este mae, se enreda y termina uno entendiendo menos'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd9630223b4173ce9dcf2f9384bbe9603f06bbfcbb250a4fcd057b4399a27e4c2'::TEXT, ARRAY[3049]::BIGINT[]),
    (212::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd4354c4149e210d3348489afd64da0816d35fcce597596660258a5c4a5d72c66'::TEXT, ARRAY[3049]::BIGINT[]),
    (212::BIGINT, 'El profe es buena gente y se preocupa por los estudiantes pero hace demasiado enredo, califica duro, los quizzes y los exámenes son complicados, se ve que sabe mucho y como profesional es bueno pero como profe no.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '9fefee6f12bf204960d5509f4f90697f6ac6ed3e8dd63234aad4b4d6e5f0acfd'::TEXT, ARRAY[3049]::BIGINT[]),
    (212::BIGINT, 'Es un profesor que frecuentemente sale hablando de otro temas perdiendo tiempo y eso vuelve la clase confusa ademas explica mal yo nunca le entendi Si es el ultimo profe que queda para matricular mejor no lleve el curso'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '22cfc391ab55bb83a9b72528b69c9f369e56b8d44f5f74165b0aa5ac6b19566f'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'El profe es bastante bueno, suele ser muy comprensivo con los estudiantes y al ser un curso un poco complicado, muestra mucho interés en que realmente comprendan la materia. Lo recomiendo bastante.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '834c3d2c8b9081313050095a813d91db384aaf72ea155aad01b71d733f7c0591'::TEXT, ARRAY[3049]::BIGINT[]),
    (212::BIGINT, 'No sé porqué tan mal calificado, realmente explica bien y brinda muucha ayuda, es muy considerado con el estudiante y muy tuanis'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, '92ff9bdb4978c96f24235edfbb482259ececc23b39774e1bdd16379aa5f19b02'::TEXT, ARRAY[3049]::BIGINT[]),
    (212::BIGINT, 'Es pésimo. Huya de aquí y matricule con otro profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'c11e2b972c9125b28aa11c894203c4edbbf8e3ffb197b8bd1c3b1d143a52ad7b'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'A cada rato dice estupideces pero eso hace que la clase no sea tan pesada. Explica bien y brinda las herramientas para poder resolver las prácticas y tareas de cátedra (para el examen también). Pasa lista todas las clases y es muy estricto con la predentación de las tareas. Sea responsable.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '2187f96c196b2ad153ac48daa341f67df49c7cd069bbaf0157aa7484d0f2a2e4'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'No me dio para nada la impresión que muchos tiene de él. Creo que es bueno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'd7c967f09fcb90914768e231cb38f5e04aa63e376550843533a2c9efb55e40a2'::TEXT, ARRAY[1369]::BIGINT[]),
    (212::BIGINT, 'No es malo como dicen, se preocupa porque los estudiantes entiendan y si usted muestra interés (vaya a consulta) todo bien. Solo es cuestión de ser responsable con el curso y pasa bien. Hay que tener cuidado porque SÍ toma en cuenta la asistencia'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2f436b40c298fb5194906327949255c3320245d537d87d97b956dd169d7804bc'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'Es ingeniero, NO profesor. Si quiere pasar con él le tiene que poner desde el primer día. A veces le ayuda a uno en consulta o a veces lo confunde más. Se preocupa demasiado por la presentación de las tareas y la asistencia.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2018-11-17T00:00:00+00:00'::TIMESTAMPTZ, '0094ecb4b295271340740907bfa1184b80d71ddcb9756a7824429f282a9d28a5'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'LO PEOR. No se lo deseo como profeso a nadie. Lamentable que una institución como el TEC tenga profesores como él. Pésimo para explicar, no ayuda en nada, tras de que califica duro, califica super mal. PÉSIMO.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, '65a6d9206c2894979984b58d23a633e46ff766059a5c92a6c7f7a13753fd89e1'::TEXT, ARRAY[922]::BIGINT[]),
    (212::BIGINT, 'Este profesor es pésimo, no se lo recomiendo a nadie. Según el es el mejor profesor de la escuela de Física, sin embargo no sabe explicar. Ademas, hace quices imposibles.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '5898828c8077b32a8f06ed12c0b014308071b0ad2038e13672081f4eff1eff85'::TEXT, ARRAY[922]::BIGINT[]),
    (212::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '7bfe3438f2d234f3b66a1c06f83112955b2eb9b92700a46fa3da68e0e0477867'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'Es un profesor terrible, no ayuda en nada y todo lo hace muy difícil, no lo recomiendo para nada.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6737a63b7705c24b93ff57d7acf01c7bf307a8a51ea18825f1826f834e4a0b57'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'Da la materia con claridad y ayuda bastante durante los laboratorios, califica los informes un poco duro.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '11955c092563108792b9896bc06c182f4c039d101ec9323fe1328aa1a4f2bc96'::TEXT, ARRAY[631]::BIGINT[]),
    (212::BIGINT, 'Es de ir a consulta y carle bien. Explica bien, deja un marco teórico a la semana y al final se hicieron solo 4 informes.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'd705f712266da33e8183000c158e0b5c8800cda74631e50062b13784475b3a07'::TEXT, ARRAY[631]::BIGINT[]),
    (212::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2018-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'fe0b69db719aa350f6189e118a66ebd2145cb35d42469ad97c000d48d3bb2076'::TEXT, ARRAY[631]::BIGINT[]),
    (212::BIGINT, 'El profe es confuso al explicar la materia, cuando considera algo importante lo repite unas mil veces ( y a veces no es importante), se sale mucho del tema y a veces no cubre por completo la materia. Pd el curso es es muy sencillo, se pasa fácil'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2018-01-02T00:00:00+00:00'::TIMESTAMPTZ, '6dd4808efb103ac2f84fce709c133111057fd1fce6ada6c03cf0d071cbc3e70b'::TEXT, ARRAY[922]::BIGINT[]),
    (212::BIGINT, 'No es muy bueno explicando y se enfoca mucho en temas que no seon muy relevantes.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, '5375b009be3ef9bdd91debddf0bfe7a91df29f84ce1158afb9115d6cbace2a1b'::TEXT, ARRAY[922]::BIGINT[]),
    (212::BIGINT, 'No explica muy bien, se nota que no domina al 100% la materia y se confunde mucho en los ejercicios. Deja muchas tareas y aveces hace quices; además nunca le da tiempo de terminar la clase a tiempo, suele desviarse mucho del tema. Califica normal.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'a0db505490b49e9d088826998476ec37d9c8817a5a40c7cd5c656d4cfafead80'::TEXT, ARRAY[922]::BIGINT[]),
    (212::BIGINT, 'De los peores profesores que he tenido en el TEC. Deja muchas tareas y pasa lista al final de la clase. Califica duro y es pésimo explicando. MALISIMO.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '16915d9ac2b441ae67036c2fad168ff1fe408c5e9f3646c6ed32e2329f660296'::TEXT, ARRAY[922]::BIGINT[]),
    (212::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2017-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'fb13c278439d13aaca8531a617e65f67dcfa928eb34431e1caf6e4d310825e37'::TEXT, ARRAY[922]::BIGINT[]),
    (212::BIGINT, 'No es buen profesor. Se desvía del tema y los ejemplos no son siempre claros, se pierde explicando. En consulta ayuda pero a veces se nota bastante que no tiene buen dominio de los temas. Se pasa fácil pero no lo recomiendo si quiere aprender.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-11T00:00:00+00:00'::TIMESTAMPTZ, '482db7302b84585ac5d1195ee6c60e7ccd9b40fe016e7f4436358e6a8ca15f1f'::TEXT, ARRAY[922]::BIGINT[]),
    (212::BIGINT, 'Física 2 es un curso duro con mucha materia. Con cualquier profe que lo meta va a tener que estudiar un poco por su propia cuenta. El profe no es el mejor explicando pero sí se preocupa por que la gente entienda. En consulta ayuda mucho y a veces da ejemplos parecidos a los ejercicios del examen.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2017-07-31T00:00:00+00:00'::TIMESTAMPTZ, '505a367defae4cbd272e92fea9c2368fc85a43b8ae6723f87cb97b2fd5f2f5ab'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (212::BIGINT, 'Ayuda bastante cuando ve el interés, es vacilón aunq en ocasiones se desvía mucho del tema, pero el curso es super pasable con él, si puede matricule con otro para no estresarse mucho pero si le toca con el no se preocupe que si pasa facil.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, '3e85409f5c5c430e666cb8be48351ea42bfbb38747e62d3c90b035a1f7d37c92'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Explica más o menos y a veces es un poco enredado. Personalmente no lo recomiendo. Generalmente lo va a escuchar hablando de que birras y de que es un buen profe'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '04c482bd35be33aa170029246ddef4af20619633ee684535f53435f5754b410a'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'Explica lo que va a salir en el examen, bastante claro. Califica rudo, vaya a consulta'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'a7bd85f878bf2d3661b0725df2120ef6804e73fb9e31eda6509f033339704e65'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (212::BIGINT, 'Explica muy bien y califica normal'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-06T00:00:00+00:00'::TIMESTAMPTZ, '19a05059887739e8d82c620a3722031a818a3ba77d82c6f566c50b3510295cae'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (212::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '4abe39e799d6e69a375db4f8202ea916ade26461c9e035b25c2bf62d1ee74b1d'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'Es buen profesor, explica lo necesario para que le vaya bien en el examen. Realiza bastantes ejercicios y en consulta es muy bueno ayudando.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, '87616ddaa08537a4443df9969d4682ec59924b29fdcd2d817660e81822be83fa'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'Si solo queda el, preparese para llevar el curso el otro semestre o estudiar por aparte.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, '15fb912b228e1ca067abed40c0eb439b40cd40e7156867a57366f2679139243d'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'c0392f9c4c3f3e01b9f6ced06957cd5672e599406eeda4dfd9b592576e5b4607'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (212::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '2321dac800b896c86a4b6e1dc9a041751c94ebfa2a2d89f5b734a796ca9f199b'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'es super facil pasar, nunca hizo quices, pedia cosas pero se le olvidaba recogerlas.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-03T00:00:00+00:00'::TIMESTAMPTZ, '96846bd54fbd03e44f4273d7f1db72d22080314761b292c4103b2e0f05a49939'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'No explica bien, tampoco se preocupa por el estudiante, deja todo para el final y califica duro.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2016-11-14T00:00:00+00:00'::TIMESTAMPTZ, '7ad82ee65f2ca2ea43491c19f1d49fa2ba1f3a777609d6d8aa126c934f065d4c'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'La mayor decepción de profesor que he visto en el TEC.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '0f8ac2f9a7a92b6a061c4a675548fd1dc92517223b940c067654cf97c58e16eb'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (212::BIGINT, 'Trata de ser "buena nota", pero como profesor no es tan bueno. Califica duro.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'e47e9e4095d7e906da568c92d3c8bc65d362a8160a53c2dea91f3f805978d081'::TEXT, ARRAY[631]::BIGINT[]),
    (212::BIGINT, 'En lo personal no estuvo tal mal nunca nos hizo quices, tal vez este semestre estaba bondadoso'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'efa4ace510828c4fbd4243beaa1fbfad0842c4373354a39bbfec3bd3612e3f51'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Mal profe, según el es buena gente, pero al calificar se le olvida y explica muy poco'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1fa6817e1138279cb54e0cd47b2f513b7be8299d38349b216346a2f83f690b9f'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (212::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '92251322763da03092f386c16171c7ac2147285f12889bd3d5263968360a0368'::TEXT, ARRAY[631]::BIGINT[]),
    (212::BIGINT, 'Lo de Lab lo explica claro, pero califica muy duro, hace quices todas las semanas, dice que va a revisar "x" informe y revisa otro... todo mundo pasó raspando. Como persona es tuanis, pero no lo recomiendo como profe.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-15T00:00:00+00:00'::TIMESTAMPTZ, '0804b635c09c5e19b508c59b7172f366940f0063d4c043d01a7b3ae4741cb208'::TEXT, ARRAY[631]::BIGINT[]),
    (212::BIGINT, 'De nada le sirve a uno que el profe sea buena nota, así se lo pongo, no lo recomiendo, apenas para el gasto este profe, los ejemplos que hace son lo más fáciles y dice que va a hacer quiz sorpresa nunca lo hace y a uno lo trama todo, PÉSIMO.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-14T00:00:00+00:00'::TIMESTAMPTZ, '7a4104cda74f69cb3970708bf2e7bbf56e11255875b174f278c42a70e8f45e9b'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'En clase lo único que hace es dar teoría, un par de ejercicios por tema pero muy básicos. Califica muy duro y no regala ni medio punto a final de semestre. Sinceramente, el peor profesor que he visto.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-29T00:00:00+00:00'::TIMESTAMPTZ, '3a28d1dac7571a81189c91d43678732f39862a11fc602a9a3fa86c8a73f3da91'::TEXT, ARRAY[630]::BIGINT[]),
    (212::BIGINT, 'Es buena persona, pero no se le entiende como explica y aparte no entrega resultados de ninguna evaluación y al final uno no sabe como va en el curso'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-27T00:00:00+00:00'::TIMESTAMPTZ, '6f8a751312a6f9dc72f6b5a7c28c6559e5fa7332494224fd14327e4ee8bc9d6f'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Como persona es buena gente aunque como profesor a veces no se le entiende mucho, trata de explicar la materia con ejemplos que solo él entiende o se le va lo que estaba explicando en pura hablada. ARDILLA ARDILLA MUCHACHOS!!!!!!'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-21T00:00:00+00:00'::TIMESTAMPTZ, 'd24482c6739f19639640d98c94879e6e99031d773932c9e7fa3cfb72a4b34caa'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'No explica también, como que no domina la materia, y dura mil años explicando un tema, habla mucho y pierde mucho tiempo, pero a veces es pura vida.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-16T00:00:00+00:00'::TIMESTAMPTZ, '6fa7d75c6ce65d2fd6475c656bfd5b4be0f0a88aa2e508f8d858f113aafeeaa2'::TEXT, ARRAY[631]::BIGINT[]),
    (212::BIGINT, 'Poco claro y se enreda solo. Por estar tratando de ser gracioso y caerle bien a todo mundo no se le entiende nada y termina aburriendo. Tiene una obsesión con las ardillas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'b61d86e5e97e77d54e9245af6e324bce01a1a4ed7071ae032c3a25fbd5c32280'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (212::BIGINT, 'A veces se enreda explicando, califica duro pero es muy buena persona y ayuda mucho en consulta'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'a18c39130f4cd550268b0a5253cad4cd488aa3689fb14bb1e25fd2e2bd7c8f58'::TEXT, ARRAY[607]::BIGINT[]),
    (212::BIGINT, 'Es fácil con el, solo es de ponerle bonito como en cualquier otro curso'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-20T00:00:00+00:00'::TIMESTAMPTZ, '1ca03d31eef15c6a274106c645ef666e8fbfee7b13fa2ad14882f18bf93261da'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'Malo explicando, se enreda bastante y suele contradecirse. Deja tareas acorde al curso aunque un toque "voladas" para lo que explica y califica duro (comparado a como explica).'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-03T00:00:00+00:00'::TIMESTAMPTZ, '27f130cc284a6672363ec5c911247e8c9c2dd2f8468a6e091ce3d274bf306af3'::TEXT, ARRAY[604]::BIGINT[]),
    (212::BIGINT, 'Suele enredarse mucho cuando da algunos ejercicios, pero en general es muy bueno! se le entiende casi todo y hace que la clase sea muy entretenida, es solo de prestarle atencion.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-10-30T00:00:00+00:00'::TIMESTAMPTZ, '678a5ff561566254f0e54802951bb3224899dfc53fd646deacdf791e912da95c'::TEXT, ARRAY[630]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
